<article class="site-mobile-layout <?= c('case', 'page') ?>" id="top"><div class="<?= c('case', 'layout') ?>"><aside class="<?= c('case', 'sidebar') ?>"><div class="<?= c('case', 'heading') ?>"><nav class="<?= c('case', 'breadcrumbs') ?>" aria-label="Хлебные крошки"><a href="/">Главная</a><span aria-hidden="true">›</span><a href="/projects">Портфолио</a><span aria-hidden="true">›</span><span aria-current="page"><?= h($case['title']) ?></span></nav><h1><?= h($case['title']) ?></h1></div><p class="<?= c('case', 'whatDone') ?>"><?= h($case['whatDone'] ?? $case['summary']) ?></p>
<?php if (trim($case['role']) !== '' || trim($case['year']) !== '' || trim($case['url']) !== ''): ?><dl class="<?= c('case', 'details') ?>"><?php if (trim($case['role']) !== ''): ?><div><dt>Роль</dt><dd><?= h($case['role']) ?></dd></div><?php endif; ?><?php if (trim($case['year']) !== ''): ?><div><dt>Год</dt><dd><?= h($case['year']) ?></dd></div><?php endif; ?><?php if (trim($case['url']) !== '' && $case['url'] !== '#'): ?><div><dt>Проект</dt><dd><a href="<?= h(normalize_url($case['url'])) ?>"<?php if (preg_match('~^https?://~i', $case['url'])): ?> target="_blank" rel="noreferrer"<?php endif; ?> aria-label="Открыть сайт <?= h($case['title']) ?>">Открыть сайт <span aria-hidden="true">↗</span></a></dd></div><?php endif; ?></dl><?php endif; ?>
</aside><div class="<?= c('case', 'content') ?>">
<?php foreach ($case['blocks'] ?? [] as $blockIndex => $block): $spacing = $block['spacing']; ?>
<?php if ($block['type'] === 'image'): ?><figure class="<?= c('case', 'block') ?>" data-spacing="<?= h($spacing) ?>"><?php if ($block['caption']): ?><figcaption><?= h($block['caption']) ?></figcaption><?php endif; ?><?php if ($block['image']): image($block['image'], $block['alt'], ['class' => c('case', 'image'), 'sizes' => '(max-width: 767px) calc(100vw - 40px), (max-width: 1024px) calc(100vw - 64px), (max-width: 1919px) 62vw, 820px'], false, $blockIndex === 0); else: ?><div class="<?= c('case', 'imagePlaceholder') ?>" role="img" aria-label="<?= h($block['alt'] ?: 'Место для изображения') ?>"><span>Изображение будет добавлено</span></div><?php endif; ?></figure>
<?php elseif ($block['type'] === 'gallery'): $images = array_filter($block['images'], fn(array $image): bool => $image['image'] !== ''); if ($images): ?><div class="<?= c('case', 'block') ?> <?= c('case', 'gallery') ?>" data-spacing="<?= h($spacing) ?>"><?php foreach (array_values($images) as $imageIndex => $item) image($item['image'], $item['alt'], ['sizes' => '(max-width: 599px) calc(100vw - 40px), (max-width: 767px) calc(50vw - 28px), (max-width: 1024px) calc(50vw - 42px), (max-width: 1919px) 31vw, 396px'], false, $blockIndex === 0 && $imageIndex === 0); ?></div><?php endif; ?>
<?php elseif ($block['type'] === 'callout'): if ($block['text']): ?><aside class="<?= c('case', 'block') ?> <?= c('case', 'callout') ?>" data-spacing="<?= h($spacing) ?>"><?php image('/assets/figma/case-callout-icon.svg', '', ['width' => 24, 'height' => 24]); ?><p><?= h($block['text']) ?></p></aside><?php endif; ?>
<?php else: ?><section class="<?= c('case', 'block') ?> <?= c('case', 'textBlock') ?>" data-spacing="<?= h($spacing) ?>"><?php if ($block['title']): ?><header><h2><?= h($block['title']) ?></h2><span></span></header><?php endif; ?><?php if ($block['body']): ?><p class="<?= c('case', 'body') ?>"><?= h($block['body']) ?></p><?php endif; ?><?php if ($block['listStyle'] !== 'none' && $block['items']): ?><ol class="<?= c('case', 'list') ?>" data-style="<?= h($block['listStyle']) ?>"><?php foreach ($block['items'] as $index => $item): ?><li><?php if ($block['listStyle'] === 'bullet'): image('/assets/figma/case-list-marker.svg', '', ['width' => 8, 'height' => 18]); elseif ($block['listStyle'] === 'numbered'): ?><span class="<?= c('case', 'number') ?>"><?= str_pad((string)($index + 1), 2, '0', STR_PAD_LEFT) ?></span><?php endif; ?><div><?php if ($item['label']): ?><span class="<?= c('case', 'itemLabel') ?>"><?= h($item['label']) ?></span><?php endif; ?><p><?= h($item['text']) ?></p></div></li><?php endforeach; ?></ol><?php endif; ?></section><?php endif; ?>
<?php endforeach; ?>
<?php $relatedCases = related_cases($content, $case); if ($relatedCases): ?><nav class="<?= c('case', 'related') ?>" aria-labelledby="related-cases-title"><h2 id="related-cases-title">Другие кейсы</h2><ul class="<?= c('case', 'relatedLinks') ?>"><?php foreach ($relatedCases as $related): ?><li><a href="/cases/<?= h($related['slug']) ?>"><?= h($related['title']) ?><span aria-hidden="true"> ↗</span></a></li><?php endforeach; ?></ul><p><a href="/#price">Услуги и стоимость <span aria-hidden="true">↗</span></a></p></nav><?php endif; ?>
</div></div></article>
